package com.bank.directory;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class InitialDemo {
    private static final Logger log = Logger.getLogger("Directory");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> names = List.of("Rajesh", "rohan", "Amit", "Priya", "", "Arun");
        DirectoryService service = new DirectoryService();

        Map<Character, List<String>> byInitial = service.byInitial(names);
        byInitial.forEach((c, list) -> log.info(() -> c + " → " + list));
    }
}

// ─── Would be in service/DirectoryService.java ───
class DirectoryService {
    Map<Character, List<String>> byInitial(List<String> names) {
        return names.stream()
            .filter(n -> n != null && !n.isBlank())          // guard empty/null
            .collect(groupingBy(
                n -> Character.toUpperCase(n.charAt(0)),       // normalise case
                TreeMap::new,                                  // alphabetical keys
                toList()));
    }
}
